-- Créole guadeloupéen (GCF) : derniers « asi » et « Benen » restés en base après 20261124. Le site écrit « asou » (124 fois)
-- et « Bénin » (28 fois). Une valeur n'est remplacée que si elle vaut encore l'ancienne (une saisie de l'équipe reste
-- intacte). Publié (valeur) et brouillon traités de même. À faire relire par un locuteur.

-- valeur
update public.contenu_site set valeur = jsonb_set(valeur, '{retourBillet}', to_jsonb($t$Ritounen asou biyé an mwen$t$::text)) where cle = 'GCF:fr.devisPage' and valeur #>> '{retourBillet}' = $t$Ritounen asi biyé an mwen$t$;
update public.contenu_site set valeur = jsonb_set(valeur, '{description}', to_jsonb($t$Ajans touris mémwa épi kilti Ouidah, an Bénin : sikwi a pyé asou Route des Esclaves, événman épi séjou préparé épi lékip ki asou plas.$t$::text)) where cle = 'GCF:site.seo' and valeur #>> '{description}' = $t$Ajans touris mémwa épi kilti Ouidah, an Benen : sikwi a pyé asou Route des Esclaves, événman épi séjou préparé épi lékip ki asou plas.$t$;
update public.contenu_site set valeur = jsonb_set(valeur, '{commande,zoneSansPrix}', to_jsonb($t$Livrézon an péyi-lasa pa pòkò pé péyé asou entènèt. Chwazi pran Ouidah oben ékri nou pou òganizé’y.$t$::text)) where cle = 'GCF:boutique.boutique' and valeur #>> '{commande,zoneSansPrix}' = $t$Livrézon an péyi-lasa pa pòkò pé péyé asi entènèt. Chwazi pran Ouidah oben ékri nou pou òganizé’y.$t$;
update public.contenu_site set valeur = jsonb_set(valeur, '{commande,paiementPlusTard}', to_jsonb($t$Péman-lan pa té pé ouvè. Zot pé péyé komand-lan asou paj suivi a’y pandan 30 minit.$t$::text)) where cle = 'GCF:boutique.boutique' and valeur #>> '{commande,paiementPlusTard}' = $t$Péman-lan pa té pé ouvè. Zot pé péyé komand-lan asi paj suivi a’y pandan 30 minit.$t$;
update public.contenu_site set valeur = jsonb_set(valeur, '{ready,surMesure,label}', to_jsonb($t$Kréyé vwayaj an mwen asou mézi$t$::text)) where cle = 'GCF:fr.cheminsIntro' and valeur #>> '{ready,surMesure,label}' = $t$Kréyé vwayaj an mwen asi mézi$t$;

